import json,hashlib,base64,html
from pathlib import Path
r=Path('data/text_quality/20261111');out=r/'cleaned_proposed_v2'
read=lambda p:[json.loads(l) for l in p.read_text(encoding='utf8').splitlines()]
qs=read(out/'cleaned_questions.jsonl');flags=read(out/'flags.jsonl');reviews={d['flag_id']:d for d in read(out/'luna_reviews_with_parent_qa.jsonl')};logs=read(out/'changes.jsonl');score=json.loads((out/'quality_scorecard.json').read_text())
byq={};images={}
for f in flags:
 d=reviews[f['flag_id']];item={**f,'review':d};byq.setdefault(f['record_id'],[]).append(item)
 for evidence in d.get('image_evidence',[]):
  p=Path(evidence['path']);key=str(p);images[key]=base64.b64encode(p.read_bytes()).decode()
 for path in d['image_paths']:
  p=Path(path)
  if p.exists():images[str(p)]=base64.b64encode(p.read_bytes()).decode()
items=[{'question_id':q['question_id'],'year_label':q['year_label'],'number':q['printed_question_number'],'pages':q['pdf_pages'],'changed':q['text_changed'],'format':q['format'],'stem':q['stem'],'original_stem':q['original_stem'],'options':q['options'],'original_options':q['original_options'],'flags':byq.get(q['question_id'],[])} for q in qs]
payload=json.dumps({'items':items,'images':images},ensure_ascii=True).replace('<','\\u003c')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><title>Question text cleanup review</title><style>body{font:16px/1.5 system-ui;max-width:1200px;margin:20px auto;padding:15px}input,select,button,textarea{font:inherit;padding:7px;margin:5px}textarea{width:95%;min-height:100px}pre{white-space:pre-wrap;overflow-wrap:anywhere}table{width:100%;border-collapse:collapse}td,th{border:1px solid #ccc;padding:9px;text-align:left;vertical-align:top;white-space:pre-wrap;overflow-wrap:anywhere}img{width:100%}code{overflow-wrap:anywhere}.bar{background:#fff;position:sticky;top:0;border:1px solid #bbb;padding:8px}summary{cursor:pointer}</style><h1>Question text cleanup review</h1><p>11 November 2026. All 1,397 in-scope question proposals were screened. Luna reviewed 1,550 flagged occurrences; parent AI rejected canonical spelling repairs where the paper itself prints the unusual spelling. There are 860 actual proposed span edits across 279 questions. This is a source-linked AI proposal layer, not human-validated extraction. Original stems, options, raw evidence and six prior acceptance decisions are preserved in the companion JSONL files.</p><p>Use Changed to inspect proposed edits; All includes unchanged questions too. Full source line crops are embedded below. Preserve printed typos; do not infer answers or legal citations. Record the scope actually checked. This deliberately selected cleanup review is separate from the blind human benchmark. Download decisions before closing: entries are not automatically saved and downloading does not apply corrections.</p><div class="bar"><select id="mode"><option value="changed">Changed questions</option><option value="flagged">All flagged questions</option><option value="all">All questions</option></select><select id="year"><option value="all">All years</option></select><input id="search" placeholder="Search text / question number"><select id="choose"></select></div><h2 id="heading"></h2><p id="id"></p><div id="comparison"></div><details><summary>Flag decisions and uncertainty</summary><div id="flags"></div></details><fieldset><legend>Human decision for this question</legend><label>Decision <select id="decision"><option value="">Unreviewed</option><option>accept</option><option>reject</option><option>unresolved</option></select></label><label>Reviewer <input id="reviewer"></label><label>Date <input type="date" id="date"></label><textarea id="notes" placeholder="Rationale, corrections, unresolved text, and exactly what you checked"></textarea><button id="download">Download decisions (.jsonl)</button></fieldset><h3>Source line crops</h3><div id="evidence"></div><script>const DATA=DATA_PLACEHOLDER;let active=null;const decisions={};const choose=document.getElementById('choose');for(let y=2016;y<=2026;y++){const o=document.createElement('option');o.value=y;o.textContent=y;document.getElementById('year').append(o);}function save(){if(!active)return;decisions[active]={decision:document.getElementById('decision').value||null,reviewer:document.getElementById('reviewer').value||null,review_date:document.getElementById('date').value||null,rationale:document.getElementById('notes').value||null};}function show(){save();active=choose.value;const item=DATA.items.find(i=>i.question_id===active);if(!item)return;document.getElementById('heading').textContent=item.year_label+' | printed Q'+item.number+' | PDF '+item.pages.join(', ')+' | '+(item.changed?'Proposed changes':'No text changes');document.getElementById('id').textContent=item.question_id;const target=document.getElementById('comparison');target.replaceChildren();const table=document.createElement('table');const header=document.createElement('tr');for(const t of ['Field','Original extraction','Cleaned proposal']){const th=document.createElement('th');th.textContent=t;header.append(th);}table.append(header);const values=[['Stem',item.original_stem,item.stem]];for(let i=0;i<Math.max(item.original_options.length,item.options.length);i++){const a=item.original_options[i],b=item.options[i];values.push(['Option '+(b||a).label,a?a.text:'[missing]',b?b.text:'[missing]']);}for(const valuesRow of values){const tr=document.createElement('tr');for(const v of valuesRow){const td=document.createElement('td');td.textContent=v;tr.append(td);}table.append(tr);}target.append(table);const ftarget=document.getElementById('flags');ftarget.replaceChildren();for(const f of item.flags){const p=document.createElement('p');p.textContent=f.flag_id+' | '+f.field+' | '+JSON.stringify(f.text)+' | '+f.review.disposition+' | replacement '+JSON.stringify(f.review.replacement)+' | '+f.review.rationale;ftarget.append(p);}const evidence=document.getElementById('evidence');evidence.replaceChildren();const keys=new Set(item.flags.flatMap(f=>f.review.image_paths));for(const key of keys){if(!DATA.images[key])continue;const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent=key;const image=document.createElement('img');image.alt='Labeled source line evidence';image.src='data:image/jpeg;base64,'+DATA.images[key];details.append(summary,image);evidence.append(details);}const d=decisions[active]||{};for(const [id,key] of [['decision','decision'],['reviewer','reviewer'],['date','review_date'],['notes','rationale']])document.getElementById(id).value=d[key]||'';}function filter(){save();const mode=document.getElementById('mode').value,year=document.getElementById('year').value,term=document.getElementById('search').value.toLowerCase();choose.replaceChildren();for(const item of DATA.items){if(mode==='changed'&&!item.changed||mode==='flagged'&&!item.flags.length||year!=='all'&&String(item.year_label)!==year)continue;if(term&&!(item.stem+' '+item.number+' '+item.options.map(o=>o.text).join(' ')).toLowerCase().includes(term))continue;const o=document.createElement('option');o.value=item.question_id;o.textContent=item.year_label+' Q'+item.number+' PDF'+item.pages.join('/');choose.append(o);}show();}choose.onchange=show;for(const id of ['mode','year'])document.getElementById(id).onchange=filter;document.getElementById('search').oninput=filter;document.getElementById('download').onclick=()=>{save();const rows=DATA.items.map(i=>({question_id:i.question_id,year_label:i.year_label,pdf_pages:i.pages,...(decisions[i.question_id]||{decision:null,reviewer:null,review_date:null,rationale:null}),scope:'question_text_cleanup_only',independent_benchmark:false}));const url=URL.createObjectURL(new Blob([rows.map(x=>JSON.stringify(x)).join('\\n')+'\\n'],{type:'application/x-ndjson'}));const a=document.createElement('a');a.href=url;a.download='human_cleanup_decisions.jsonl';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};filter();</script></html>'''.replace('DATA_PLACEHOLDER',payload)
page=page.replace('Luna reviewed 1,550 flagged occurrences',f"Luna reviewed {score['reviewed_flag_occurrences']:,} flagged occurrences").replace('860 actual proposed span edits',f"{score['actual_span_changes']:,} actual proposed edits (including two source-field retranscriptions)")
(out/'review.html').write_text(page,encoding='utf8')
text=['AI-PROPOSED QUESTION TEXT CLEANUP | 11 November 2026','1,397 in-scope proposals. Not human-validated. Preserve source spelling and uncertainty.','Originals and change logs are in companion JSONL files.\n']
for q in qs:
 text.extend([f"{q['year_label']} | Printed Q{q['printed_question_number']} | PDF pages {','.join(map(str,q['pdf_pages']))}",q['question_id'],q['stem']])
 text.extend(f"({o['label']}) {o['text']}" for o in q['options']);text.append('')
(out/'cleaned_questions.txt').write_text('\n'.join(text),encoding='utf8')
(out/'review_manifest.json').write_text(json.dumps({'items':len(items),'embedded_source_sheets':len(images),'decision_fields':'blank','outputs':{n:hashlib.sha256((out/n).read_bytes()).hexdigest() for n in ['review.html','cleaned_questions.txt']},'human_validated':False},indent=2),encoding='utf8')
print(len(items),'items;',len(images),'embedded source sheets;',round((out/'review.html').stat().st_size/1e6,1),'MB')
